186	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
187	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
188	
189	        try {
190	            // 예시: 로직 단순화
191	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
192	            Document doc = Jsoup.connect(url).get();
193	            // tbody#statusDetail 의 마지막 tr => 5번째 td
194	            Elements rows = doc.select("tbody#statusDetail tr");
195	            if (rows.isEmpty()) {
196	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
197	                throw new ShipmentException(
